o.x:
var $bm_rt;
var dur, t;
dur = 2;
$bm_rt = t = $bm_mod(time, dur);
if (t < 0.35) {
    $bm_rt = ease(t, 0, 0.35, 0, 100);
} else if (t < 1.35) {
    $bm_rt = 100;
} else {
    $bm_rt = ease(t, 1.35, 2, 100, 0);
}

r.x:
var $bm_rt;
var dur, t;
dur = 2;
t = $bm_mod(time, dur);
$bm_rt = $bm_mul(Math.sin($bm_mul($bm_mul($bm_div(t, dur), Math.PI), 2)), 5);

p.x:
var $bm_rt;
var dur, delay, t, p, direction, distanceX, distanceY, x, y;
seedRandom(index, true);
dur = 2.4;
delay = random(0, 1.4);
t = $bm_mod($bm_sum($bm_sub(time, delay), dur), dur);
p = $bm_div(t, dur);
direction = random(-1, 1);
distanceX = random(25, 55);
distanceY = random(100, 145);
x = $bm_sum($bm_sum(value[0], $bm_mul($bm_mul(direction, distanceX), ease(p, 0, 1, 0, 1))), $bm_mul(Math.sin($bm_mul($bm_mul(p, Math.PI), 2)), 6));
y = $bm_sub(value[1], ease(p, 0, 1, 0, distanceY));
$bm_rt = [
    x,
    y
];

